              "html": "The word standing immediately before the مَوْصُوْلٌ tells you the slot. A demonstrative before it makes it a مُشَارٌ إِلَيْهِ. A noun without ال and without tanwīn before it makes it a مُضَافٌ إِلَيْهِ. A حَرْفُ جَرٍّ before it makes it a مَجْرُوْرٌ. A complete مَعْرِفَةٌ noun before it — one that is already fully defined — makes it a نَعْتٌ.",
